import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"takoform_resource","description":"Generic Host API v1alpha3 carrier for any Form, including third-party Forms, addressed by exact FormRef.","frontmatter":{"page_title":"takoform_resource Resource - takoform","subcategory":"Host API v1alpha3","description":"Generic Host API v1alpha3 carrier for any Form, including third-party Forms, addressed by exact FormRef."},"headers":[],"relativePath":"docs/resources/resource.md","filePath":"docs/resources/resource.md"}'),i={name:"docs/resources/resource.md"};function s(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="takoform-resource" tabindex="-1">takoform_resource <a class="header-anchor" href="#takoform-resource" aria-label="Permalink to &quot;takoform_resource&quot;">​</a></h1><p>Carries any Host API v1alpha3 Form by exact FormRef, including Forms published by third parties in their own API groups. It is not a Form and has no FormRef of its own: the configuration names the exact reference plus one JSON desired spec, so a Form this provider was never built against is still usable.</p><p>This resource speaks the Host API v1alpha3 lane and requires provider v2.1.0 or later (source candidate; not yet published). The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="../../examples/resources/takoform_resource/resource.tf">complete example</a>.</p><p>Prefer a typed resource where one exists: the Edge Platform Family resources carry per-field validation, a typed plan, and short import IDs. This carrier trades all three for reach — it imports too, but only through the exact identity it cannot infer.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><p>The four <code>form_*</code> attributes are the exact FormRef. They, <code>name</code>, and <code>space</code> all force replacement, so existing state is never rebound to another identity.</p><ul><li><code>form_api_version</code> (String, required, forces replacement) — Exact namespaced Form group and version, for example <code>forms.example.com/v1alpha1</code>. The frozen <code>forms.takoform.com/v1alpha1</code> and <code>forms.takoform.com/v1alpha2</code> groups are rejected; retained-epoch Forms belong to the provider-v2 typed resources.</li><li><code>form_kind</code> (String, required, forces replacement) — Exact Form kind, matching <code>^[A-Z][A-Za-z0-9]{0,63}$</code>.</li><li><code>form_definition_version</code> (String, required, forces replacement) — Exact immutable Form definition version, a semantic version.</li><li><code>form_schema_digest</code> (String, required, forces replacement) — Exact immutable Form schema digest, <code>sha256:</code> followed by 64 lowercase hexadecimal characters.</li><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>), matching <code>^[a-z][a-z0-9-]{0,62}$</code>.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>spec_json</code> (String, optional) — The portable desired spec as one JSON object string (for example <code>jsonencode({...})</code>); the provider sends the parsed object as <code>spec</code>. Omitting it means the empty spec <code>{}</code>.</li><li><code>create_timeout</code> / <code>update_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>20m</code> / <code>30m</code>).</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes. Updates fence on it together with <code>uid</code>.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, or new outputs. Deletes fence on it via <code>If-Match</code>.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — JSON-serialized <code>status.outputs</code> document (<code>&quot;{}&quot;</code> when empty).</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes an in-place re-apply, which is all a host needs to re-resolve and re-pin every reference. A Form whose Definition omits <code>update</code> refuses that apply, naming the missing capability; replace the resource instead. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><p>State records the four FormRef fields and no package digest: the distribution a host installed is audit evidence, never resource identity.</p><h2 id="no-local-schema-compilation" tabindex="-1">No local schema compilation <a class="header-anchor" href="#no-local-schema-compilation" aria-label="Permalink to &quot;No local schema compilation&quot;">​</a></h2><p>The provider neither fetches nor compiles the Form&#39;s desired schema:</p><ul><li>at plan time it checks only that the four FormRef fields are wholly known and satisfy the FormRef grammar and that <code>spec_json</code> parses as one JSON object; it reads no Form Definition and makes no host call;</li><li>before each apply the client requires <code>GET {api}/forms</code> to return that exact FormRef as installed, executable, activated, available to the principal, and supporting the requested operation, then calls <code>prepare</code> and <code>apply</code>;</li><li>the host validates <code>spec</code> against that exact Form&#39;s <code>desiredSchema</code>, so a spec that violates the Form surfaces as a host <code>invalid_argument</code> error during apply rather than as a plan-time diagnostic.</li></ul><p>Reads compare <code>spec_json</code> semantically rather than textually: your formatting survives while the parsed document still equals the host&#39;s <code>spec</code>, and a real out-of-band change adopts the host&#39;s canonical serialization so the next plan shows the drift.</p><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides.</li></ul><h2 id="write-the-form-s-defaults-explicitly" tabindex="-1">Write the Form&#39;s defaults explicitly <a class="header-anchor" href="#write-the-form-s-defaults-explicitly" aria-label="Permalink to &quot;Write the Form&#39;s defaults explicitly&quot;">​</a></h2><p>A host materializes the portable defaults a Form declares before it validates, digests, or stores your spec, so the <code>spec</code> it serves back can carry properties your <code>spec_json</code> omitted. Because this carrier reads no Form Definition, it cannot fill those defaults into the plan, and a read that adopts the host&#39;s materialized document leaves a difference the next plan proposes again — each apply is a host no-op that never advances <code>generation</code>, and the difference returns. Write every defaulted property explicitly in <code>spec_json</code>, or use the typed resource for that Form where one exists: typed resources carry each declared default in the schema, so an omitted attribute plans as the value the host will materialize and the second plan is empty.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>The import ID is one JSON object naming the exact identity. It is not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_resource.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;forms.example.com/v1alpha1&quot;,&quot;kind&quot;:&quot;ExampleWidget&quot;,&quot;definitionVersion&quot;:&quot;1.0.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;example-widget&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; every other member is required. The <code>NAME</code> and <code>SPACE/NAME</code> short forms the typed family resources accept are refused here: this carrier has no default create ref to resolve them against, and guessing one would bind state to a Form the resource may not be.</p><p>Import writes exactly the identity you state and nothing else; the refresh that follows is what verifies it against the host, and <code>spec_json</code> is adopted from the host&#39;s materialized spec there. Nothing about the carrier&#39;s trust model changes: no Form Definition is fetched and no schema is compiled.</p>`,23)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
